{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C09"],
      "claim": "Lycopene, a highly lipophilic C40 isoprenoid/polyene, showed only 0.17% systemic availability after oral tomato paste in humans, providing direct evidence that long-chain lipophilic isoprenoids can have F far below 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C13"],
      "claim": "Tocotrienol-rich palm oil fraction had poor oral bioavailability in humans, supporting low F for lipophilic isoprenoid natural products.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "Phytoene, a non-conjugated C40 isoprenoid hydrocarbon, had 58.5% absolute bioavailability in humans, showing that some highly lipophilic isoprenoids can be well absorbed; this contradicts a low prediction but is limited by phytoene's lower molecular weight and lack of the quinone head.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C11"],
      "claim": "Hyperforin, a lipophilic prenylated natural product, showed high oral bioavailability in volunteers, providing weaker contradictory evidence due to lower structural similarity to the query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is an extremely lipophilic, high-molecular-weight ubiquinone-like polyisoprenoid (MW ~863, logP ~17.9, no ionizable groups). Although phytoene demonstrates that some non-conjugated isoprenoid hydrocarbons can be well absorbed, the query's much larger size and the direct low-availability evidence from lycopene and tocotrienols support F < 20%. Physicochemical liabilities in solubility and dissolution further reinforce a low oral bioavailability prediction.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for the query molecule (CoQ-like ubiquinone) in humans.",
    "Phytoene's high bioavailability may not scale to the query's higher molecular weight and quinone-containing polar head.",
    "Lycopene bioavailability estimates vary widely (0.17% to ~24%), introducing uncertainty in extrapolating from carotenoid evidence.",
    "Formulation dependence of highly lipophilic compounds is not captured by the available evidence."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

